package com.arrow.systemui.cc.controller; import android.content.*; import android.net.Uri; import android.provider.Settings;
public class BrightnessController {private final Context context;private final ContentResolver resolver;public BrightnessController(Context c){context=c;resolver=c.getContentResolver();}public boolean canWrite(){return Settings.System.canWrite(context);}public void openWriteSettings(){Intent i=new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS, Uri.parse("package:"+context.getPackageName()));i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);context.startActivity(i);}public int getBrightness(){try{return Settings.System.getInt(resolver,Settings.System.SCREEN_BRIGHTNESS);}catch(Exception e){return 128;}}public boolean setBrightness(int value){if(!canWrite())return false;try{int v=Math.max(0,Math.min(255,value));Settings.System.putInt(resolver,Settings.System.SCREEN_BRIGHTNESS_MODE,Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL);Settings.System.putInt(resolver,Settings.System.SCREEN_BRIGHTNESS,v);return true;}catch(Exception e){return false;}}public boolean isAutoBrightness(){try{return Settings.System.getInt(resolver,Settings.System.SCREEN_BRIGHTNESS_MODE)==Settings.System.SCREEN_BRIGHTNESS_MODE_AUTOMATIC;}catch(Exception e){return false;}}}
